window.POETRY_REGISTER("v5-strict-10-8-0-36f55fa1c96f.js",{"poems":[[3109,2],[14475,2],[23634,2],[40381,2],[52090,2],[52539,2],[55432,2],[59144,7],[59145,7],[62552,7],[63058,7],[63101,7],[79723,7],[87372,7],[121646,7],[121725,7],[125885,7],[134641,7],[182228,7],[191728,7],[192118,7],[197070,7],[221362,7],[221365,7],[233445,7],[241267,7],[241268,7],[259479,7],[262055,7],[274572,7],[299347,7],[304917,7],[339516,9],[345996,9],[366882,9],[409005,8],[444004,8],[451246,8],[451833,8],[453259,8],[471430,8],[484820,8],[496026,8],[502476,8],[511881,8],[552285,8],[572010,8],[627644,8],[637840,15],[650074,5],[650384,5],[672725,5],[682328,5],[688158,5],[720040,5],[720043,5],[720047,5],[727208,5],[735220,5]],"pairs":[["乍可为天上牵牛织女星","不愿为庭前红槿枝",0],["谅理性之不等于顺时兮","不如瘗吾心以冥想",1],["乍可为天上牵牛织女星","不愿为庭前红槿枝",2],["应不知天地造化是何物","亦不知荣辱是何主",3],["甲卷题作敦煌古迹廿咏","乙卷廿咏作二十咏",4],["又曾任金部司勋员外郎","约卒于大中六年后",5],["然考此诗殊不似唐人作","疑即梵徒托名为也",6],["望几点渔灯隐映蒹葭浦","停画桡两两舟人语",7],["自别后风亭月榭孤欢聚","刚断肠惹得离情苦",7],["暗惹起云愁雨恨情何限","从卧来展转千馀遍",8],["似恁地深情密意如何拼","虽后约的有于飞愿",8],["是即是从来好事多磨难","就中我与你才相见",9],["又只恐日疏日远衷肠变","便忘了当本深深愿",9],["又还是当年我向江南兴","移画船深渚蒹葭映",10],["梦回处诗塘春草愁难整","官情与归期终朝竞",10],["命小辔翩翩随处金尊倒","从市人拍手拦街笑",11],["似近日曾教青鸟传佳耗","学凤箫拟入烟萝道",11],["三四君子只是争些闲气","争如臣向青山顶头",12],["使八极顶目者不自争衡","见斯人兮驾御昂枿",13],["潺潺泠泠兮可以冰人心","胡为其气兮能毒淫",14],["我请弃冠释带以投依兮","师则指乎未契之缘",15],["何必每念辄得应余若响","坐有如此兮人子期",16],["故能屈御手调羹而亲饷","命力士脱靴而不疑",17],["三千里外逢人东倒西㒦","十字街头遇贱则贵",18],["可怜只有些儿栗棘金圈","尽底分付常山林泉",19],["青螭白虬兮不须款帝居","请发镞兮何必天弧",20],["嗟乎越山高兮可夷而丘","鉴湖深兮可理而畴",21],["舍己躁进而谓子躁进兮","宜不曰沽名之非愚",22],["帝亦悲伤而末如之何兮","磔不若魑魅而不厌",23],["首阳河渎远而不可适兮","视申子夷齐其有故",24],["亶元后天覆无我若汝兮","董尔僚厘吾天序兮",25],["亶元老地载无我若人兮","麾尔校迪吾天伦兮",26],["何必三到投子掘地觅天","雪拥鳌山一场败阙",27],["虽然不愈于无田而游兮","岁晏凄其桑落之下",28],["荷佛祖慧命于将仆之际","转凡夫于贤圣之域",29],["君不见辽东仙子丁令威","向神清而上刷羽仪",30],["夫是之谓慈林克家之子","真鸾胶而续弦者也",31],["恰不道人到中年万事休","我怎肯虚度了春秋",32],["彼失此得兮何异于梦鹿","朝三暮四兮奚取乎",33],["恰不道人到中年万事休","我怎肯虚度了春秋",34],["妇云母乎河水清且沦漪","吾往从之乐不可遏",35],["外缜内贞羌有此淑行兮","材倨不振知受命兮",36],["出八极兮睨洚淫而不即","公无渡河兮公既没",37],["吾诚不测夫子之妙用兮","固将等廊庙于江湖",38],["为家吾宁为地上之茂草","诚不忍负岩墙而生",39],["吁嗟太昊封姨兮难久依","亦能布春兮送春归",40],["君之归兮云缤缤其来迎","君不归兮使我心怦",41],["我则是寸心惟有天知道","长日里翘首仰青霄",42],["眠龙痴蛟鞭其尾而不飞","唯有蛰龙闻雷而起",43],["夫何风雨摧败而不葺兮","坐视为草莽之堙塞",44],["闻古人兮陟升皇而临睨","谁能无回首兮三叹",45],["但见山青青而林苍苍兮","掩映湛湛乎之太虚",46],["闻古人兮陟升皇而临睨","谁能无回首兮三叹",47],["君言箪疏瓢水乐不可支","妾言朝不舂暮苦饥",48],["那老虎前生修下几般福","生嚼人肉不怕塞牙",49],["从古来三百二十八万载","几句街谈要讲上来",49],["小武庚作起一辈中兴主","诛杀逆臣屠了镐京",49],["虽说是人生莫受老来贫","也须要阴骘积儿孙",50],["我欲死埋其侧生与之游","不醉亦醉不愁亦愁",51],["换眼底衰红败翠供愁写","窥冷檠半落吟边灺",52],["叹去后阑干一霎花开谢","空怨啼望帝春魂化",52],["见无限残阳衰草凝秋色","有乱馀野老犹能识",53],["想当日孤臣壮志坚如石","到而今遗血犹凝碧",53],["地僻左狂澜不到鸣榔浦","莺比邻近接青青树",54],["事到此菟裘息壤臣归路","莫浪吟惹起鱼龙舞",54],["望昭阳笙歌镫火宵连曙","山海誓输与长生语",55],["曾几日铜铺玉戺空朝暮","故剑求传说终无据",55],["说旧事凄凉背拥樊通髻","膏自煎总为凡心缀",56],["羡公子风流儒雅相知晚","更寄来笺纸光璀粲",57],["盥薇露轻轻开匣番番展","愧斜行淡墨添拘管",57],["虽说是人生莫受老来贫","也须要阴骘积儿孙",58]]});
